export interface IBatchItem<T, R> {
    item: T;
    resolve: (value: R) => void;
    reject: (error: Error) => void;
}

export interface IBatchProcessorOptions<T, R> {
    batchSize?: number;
    flushInterval?: number;
    executeBatch: (items: T[]) => Promise<R[]>;
    onError?: (error: Error, item: T) => void;
}

export class BatchProcessor<T, R> {
    private queue: Array<IBatchItem<T, R>> = [];
    private timer: ReturnType<typeof setTimeout> | null = null;
    private readonly batchSize: number;
    private readonly flushInterval: number;
    private readonly executeBatch: (items: T[]) => Promise<R[]>;
    private readonly onError?: (error: Error, item: T) => void;
    private processing = false;

    public constructor(options: IBatchProcessorOptions<T, R>) {
        this.batchSize = options.batchSize ?? 10;
        this.flushInterval = options.flushInterval ?? 50;
        this.executeBatch = options.executeBatch;
        this.onError = options.onError;
    }

    public add(item: T): Promise<R> {
        return new Promise((resolve, reject) => {
            this.queue.push({ item, resolve, reject });
            this.scheduleFlush();
        });
    }

    public addMany(items: T[]): Promise<R[]> {
        return Promise.all(items.map((item) => this.add(item)));
    }

    public flush(): Promise<void> {
        if (this.processing || this.queue.length === 0) {
            return Promise.resolve();
        }

        this.processing = true;
        const batch = this.queue.splice(0, this.batchSize);

        const items = batch.map((b) => b.item);

        return this.executeBatch(items)
            .then((results) => {
                batch.forEach((item, index) => {
                    item.resolve(results[index]);
                });
            })
            .catch((error) => {
                batch.forEach((item) => {
                    const err = error instanceof Error ? error : new Error(String(error));
                    if (this.onError) {
                        this.onError(err, item.item);
                    }
                    item.reject(err);
                });
            })
            .finally(() => {
                this.processing = false;
                if (this.queue.length > 0) {
                    this.scheduleFlush();
                }
            });
    }

    public getQueueSize(): number {
        return this.queue.length;
    }

    public clear(): void {
        if (this.timer) {
            clearTimeout(this.timer);
            this.timer = null;
        }

        const rejected = new Error("Batch processing cancelled");
        this.queue.forEach((item) => {
            item.reject(rejected);
        });
        this.queue = [];
    }

    private scheduleFlush(): void {
        if (this.timer) {
            return;
        }

        this.timer = setTimeout(() => {
            this.timer = null;
            this.flush();
        }, this.flushInterval);
    }
}

export interface IBatchResult<T> {
    success: boolean;
    item: T;
    error?: Error;
}

export async function processInBatches<T>(
    items: T[],
    processor: (item: T) => Promise<void>,
    batchSize: number = 10,
): Promise<IBatchResult<T>[]> {
    const results: IBatchResult<T>[] = [];

    for (let i = 0; i < items.length; i += batchSize) {
        const batch = items.slice(i, i + batchSize);

        for (const item of batch) {
            try {
                await processor(item);
                results.push({ success: true, item });
            } catch (error) {
                results.push({
                    success: false,
                    item,
                    error: error instanceof Error ? error : new Error(String(error)),
                });
            }
        }
    }

    return results;
}

export function createBatchedExecutor<T, R>(
    executeBatch: (items: T[]) => Promise<R[]>,
    options?: { batchSize?: number; flushInterval?: number },
): (item: T) => Promise<R> {
    const processor = new BatchProcessor<T, R>({
        ...options,
        executeBatch,
    });

    return (item: T): Promise<R> => processor.add(item);
}

export enum BatchProfile {
    IO_INTENSIVE = "io-intensive",
    CPU_INTENSIVE = "cpu-intensive",
    LOW_LATENCY = "low-latency",
    HIGH_THROUGHPUT = "high-throughput",
}

export interface BatchProcessorPresetConfig {
    batchSize: number;
    flushInterval: number;
    description: string;
}

export const BATCH_PRESETS: Record<BatchProfile, BatchProcessorPresetConfig> = {
    [BatchProfile.IO_INTENSIVE]: {
        batchSize: 25,
        flushInterval: 100,
        description: "Optimized for I/O operations like network requests. Larger batches reduce overhead.",
    },
    [BatchProfile.CPU_INTENSIVE]: {
        batchSize: 5,
        flushInterval: 200,
        description: "Optimized for CPU-bound operations. Smaller batches prevent blocking.",
    },
    [BatchProfile.LOW_LATENCY]: {
        batchSize: 5,
        flushInterval: 20,
        description: "Optimized for low latency. Fast flushing for time-sensitive operations.",
    },
    [BatchProfile.HIGH_THROUGHPUT]: {
        batchSize: 50,
        flushInterval: 500,
        description: "Optimized for maximum throughput. Larger batches, longer wait for efficiency.",
    },
};

export function createPresetBatchProcessor<T, R>(
    executeBatch: (items: T[]) => Promise<R[]>,
    profile: BatchProfile = BatchProfile.IO_INTENSIVE,
    onError?: (error: Error, item: T) => void,
): BatchProcessor<T, R> {
    const config = BATCH_PRESETS[profile];
    return new BatchProcessor<T, R>({
        batchSize: config.batchSize,
        flushInterval: config.flushInterval,
        executeBatch,
        onError,
    });
}

export function getPresetConfig(profile: BatchProfile): BatchProcessorPresetConfig {
    return BATCH_PRESETS[profile];
}
